insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O art. 4º da antiga Lei de Abuso de Autoridade foi acrescido da alínea i, que considerava abuso de autoridade prolongar a execução de prisão temporária, de pena ou de medida de segurança, deixando de expedir em tempo oportuno ou de cumprir imediatamente ordem de liberdade.', '["Alterou a antiga Lei de Abuso de Autoridade.","Prolongar a execução da prisão era abuso."]'::jsonb, '["Dispositivo histórico: a antiga lei foi substituída pela Lei de Abuso de Autoridade atual."]'::jsonb, 'Demorar para soltar o preso temporário ao fim do prazo era abuso de autoridade.', '["Assertiva que considera a alínea i vigente na antiga lei erra: ela foi substituída."]'::jsonb, '[]'::jsonb, '["Lei de Abuso de Autoridade"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'temporaria' and u.unit_key = 'art-4'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Em todas as comarcas e seções judiciárias haverá um plantão permanente de vinte e quatro horas do Poder Judiciário e do Ministério Público para apreciação dos pedidos de prisão temporária.', '["Plantão permanente de vinte e quatro horas.","Judiciário e Ministério Público.","Em todas as comarcas e seções judiciárias."]'::jsonb, '["Garante a apreciação a qualquer hora."]'::jsonb, 'O pedido de prisão temporária feito na madrugada é apreciado pelo juiz de plantão.', '["Assertiva que restringe o plantão ao Judiciário erra: inclui o Ministério Público."]'::jsonb, '[]'::jsonb, '["Art. 2º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'temporaria' and u.unit_key = 'art-5'
